import Link from 'next/link';
export const metadata = { title: 'Cookies and browser storage' };
export default function CookiesPage() {
  return <main className="mx-auto max-w-3xl space-y-6 px-4 py-12 leading-7"><h1 className="text-3xl font-bold">Cookies and browser storage</h1><p>Updated October 4, 2026. The application uses necessary browser storage for sign-in sessions and security. Local demo mode can store sample activity. Session records can remain until sign-out, expiry or manual browser-data removal.</p><p>There are no optional analytics or advertising integrations in this release, so there is no “accept all cookies” control or preselected advertising consent. Essential storage cannot be disabled while retaining all sign-in features. You can browse signed out and clear site data in your browser.</p><p>Infrastructure providers may process connection and security information separately. Clearing browser data does not delete your account, posts, messages, backups or support correspondence. Future tracking must be separately reviewed and disclosed before it loads.</p><p><Link href="/privacy-choices" className="text-teal-700 underline">Privacy choices</Link>{' · '}<Link href="/privacy" className="text-teal-700 underline">Full privacy notice</Link></p></main>;
}

import Link from 'next/link';
export const metadata = { title: 'Your privacy choices' };
export default function PrivacyChoicesPage() {
  return <main className="mx-auto max-w-3xl space-y-6 px-4 py-12 leading-7"><h1 className="text-3xl font-bold">Your privacy choices</h1><section><h2 className="text-xl font-bold">No advertising or sale/sharing in the current app</h2><p>Optional tracking, targeted advertising and sale/sharing for cross-context behavioral advertising are off for everyone. Global Privacy Control and Do Not Track do not turn anything on. There is no advertising consent to give or withdraw in this release. This page does not send opt-outs to unrelated external sites.</p></section><section><h2 className="text-xl font-bold">Access, correction, deletion, copies and appeals</h2><p>Email the temporary contact below with the subject “Privacy request” or “Privacy appeal.” Describe your request, public handle or relevant page links, and how we can reply. An account is not required. If acting as an authorized agent, tell us that; verification may be needed. Do not include passwords, codes, passports or full case files.</p><a className="break-all text-teal-700 underline" href="mailto:varunchinna5966@gmail.com?subject=VisaThreads%20privacy%20request">Email VisaThreads about privacy</a><p>Requests are handled manually. Automated export/deletion, a final retention schedule and a staffed response process are not yet established. Applicable legal rights and deadlines are not waived by this limitation. To appeal a response, reply with “Privacy appeal”; you may also contact your state’s privacy regulator or attorney general.</p></section><p><Link href="/privacy" className="text-teal-700 underline">Full privacy notice</Link>{' · '}<Link href="/contact" className="text-teal-700 underline">Other reports and support</Link></p></main>;
}
